    { name: 'cat', category: 'Mammals', fact: 'Cats purr when they are happy and sleep a lot.', svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#fefce8"/><path d="M72 74l-14-20 16 4z" fill="#f97316"/><path d="M128 74l14-20-16 4z" fill="#f97316"/><circle cx="100" cy="116" r="46" fill="#fb923c"/><circle cx="84" cy="110" r="5" fill="#431407"/><circle cx="116" cy="110" r="5" fill="#431407"/><path d="M96 128l4 5 4-5" stroke="#431407" stroke-width="3" fill="none"/><path d="M100 134c0 4-2 6-5 6s-5-2-5-6" stroke="#431407" stroke-width="3" fill="none"/><path d="M60 116h-8M60 124h-6M140 116h8M140 124h6" stroke="#431407" stroke-width="2.5"/></svg>' },
    { name: 'dog', category: 'Mammals', fact: 'Dogs are loyal friends with an amazing sense of smell.', svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#f0fdf4"/><ellipse cx="64" cy="116" rx="18" ry="30" fill="#92400e"/><ellipse cx="136" cy="116" rx="18" ry="30" fill="#92400e"/><circle cx="100" cy="116" r="46" fill="#b45309"/><ellipse cx="100" cy="136" rx="20" ry="14" fill="#fde68a"/><circle cx="87" cy="108" r="5" fill="#1c1917"/><circle cx="113" cy="108" r="5" fill="#1c1917"/><ellipse cx="100" cy="128" rx="6" ry="4" fill="#1c1917"/><path d="M100 134c0 8-3 12-8 12s-8-4-8-12" stroke="#1c1917" stroke-width="3" fill="none"/><path d="M100 146c-3 6-6 8-10 8 2-6 5-8 10-8z" fill="#ef4444"/></svg>' },
    { name: 'camel', category: 'Mammals', fact: 'A camels hump stores fat so it can travel far in the desert.', svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#fefce8"/><ellipse cx="100" cy="140" rx="46" ry="24" fill="#d97706"/><circle cx="82" cy="104" r="18" fill="#d97706"/><circle cx="116" cy="104" r="18" fill="#d97706"/><rect x="150" y="66" width="12" height="44" rx="6" fill="#d97706"/><ellipse cx="156" cy="66" rx="14" ry="12" fill="#d97706"/><circle cx="160" cy="62" r="3" fill="#431407"/><path d="M146 70l-8-6M152 78l-8 2" stroke="#b45309" stroke-width="3" fill="none"/><rect x="70" y="160" width="8" height="24" fill="#b45309"/><rect x="122" y="160" width="8" height="24" fill="#b45309"/></svg>' },
    { name: 'seal', category: 'Marine', fact: 'Seals are playful swimmers that rest on beaches and ice.', svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="#e0f2fe"/><ellipse cx="100" cy="120" rx="34" ry="44" fill="#64748b"/><circle cx="100" cy="66" r="26" fill="#64748b"/><circle cx="88" cy="60" r="4" fill="#0f172a"/><circle cx="108" cy="60" r="4" fill="#0f172a"/><ellipse cx="100" cy="72" rx="6" ry="5" fill="#0f172a"/><path d="M66 108c-14 6-20 16-18 26 14 2 22-6 22-18z" fill="#64748b"/><path d="M134 108c14 6 20 16 18 26-14 2-22-6-22-18z" fill="#64748b"/><path d="M60 156c12-8 22-8 32 0M108 156c12-8 22-8 32 0" stroke="#64748b" stroke-width="8" stroke-linecap="round" fill="none"/><circle cx="100" cy="150" r="12" fill="#ef4444"/></svg>' }
